import csv
import io
import re
from typing import Any


def parse_csv(raw_csv: str) -> dict[str, Any]:
    text = raw_csv.lstrip("\ufeff")
    lines = text.splitlines(keepends=True)

    start = 0
    while start < len(lines):
        stripped = lines[start].strip()
        if not stripped or stripped.startswith("#"):
            start += 1
        else:
            break

    body = "".join(lines[start:])
    if not body:
        return {"columns": [], "rows": []}

    delimiters = [",", "\t", ";", "|"]
    best_delimiter = ","
    best_records: list[list[str]] = []
    best_score: tuple[int, int, int, int] | None = None

    for order, delimiter in enumerate(delimiters):
        try:
            records = list(
                csv.reader(
                    io.StringIO(body, newline=""),
                    delimiter=delimiter,
                    quotechar='"',
                    strict=False,
                )
            )
        except csv.Error:
            continue

        widths = [len(record) for record in records if record]
        separated = [width for width in widths if width > 1]
        score = (
            sum(width - 1 for width in separated),
            len(separated),
            max(separated, default=0),
            -order,
        )
        if best_score is None or score > best_score:
            best_score = score
            best_delimiter = delimiter
            best_records = records

    if not best_records:
        best_records = list(
            csv.reader(
                io.StringIO(body, newline=""),
                delimiter=best_delimiter,
                quotechar='"',
                strict=False,
            )
        )

    records = [record for record in best_records if record]
    if not records:
        return {"columns": [], "rows": []}

    return {"columns": records[0], "rows": records[1:]}
